package net.spell_engine.api.loot; import java.util.*; public class LootConfigV2 { public LinkedHashMap<String,Pool> injectors=new LinkedHashMap<>(),regex_injectors=new LinkedHashMap<>(); public static class Pool{public float rolls=1,bonus_rolls=.2F;public List<Entry> entries=new ArrayList<>();public Pool rolls(double v){rolls=(float)v;return this;}public Pool bonus_rolls(double v){bonus_rolls=(float)v;return this;}public Pool add(Entry e){entries.add(e);return this;}public Pool add(String id){return add(id,false);}public Pool add(String id,boolean enchant){return add(id,0,enchant);}public Pool add(String id,int weight,boolean enchant){var e=new Entry(id);if(weight>0)e.weight=weight;if(enchant)e.enchant();entries.add(e);return this;}public static class Entry{public String id;public int weight=1;public Enchant enchant;public Entry(String id){this.id=id;}public Entry enchant(){enchant=new Enchant();return this;}public Entry enchant(int min,int max){enchant=new Enchant(min,max);return this;}public static class Enchant{public float min_power=1,max_power=30;public boolean allow_treasure=true;public Enchant(){}public Enchant(float min,float max){min_power=min;max_power=max;}public boolean isValid(){return min_power>0&&max_power>min_power;}}}} public static LootConfigV2 constrainValues(LootConfigV2 c){if(c.injectors!=null)for(var p:c.injectors.values())for(var e:p.entries)e.weight=Math.max(1,e.weight);return c;} }
